:root{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC",system-ui,sans-serif;font-size:13px;line-height:1.45;color:var(--od-ink);background:var(--od-bg);color-scheme:light}
*{box-sizing:border-box}
[hidden]{display:none!important}
body{display:flex;flex-direction:column;margin:0;background:var(--od-bg)}
input,select,textarea{width:100%;min-width:0;border:1px solid var(--od-input-border);border-radius:var(--radius-control);background:var(--od-paper);color:var(--od-ink);font:inherit;padding:var(--space-2) var(--space-3)}
input,select{min-height:36px}
input[type=checkbox]{width:auto;min-height:0;margin-right:6px}
textarea{display:block;margin:var(--space-2) 0 var(--space-3);font:var(--od-note-size)/1.55 ui-monospace,SFMono-Regular,Consolas,monospace;resize:vertical;tab-size:2}
button{max-width:100%;border:0;border-radius:var(--radius-control);background:var(--od-brand);color:var(--od-on-brand);padding:var(--space-2) var(--space-3);min-height:34px;font:inherit;cursor:pointer;overflow-wrap:anywhere}
button:disabled{opacity:.48;cursor:not-allowed}
button:hover:not(:disabled){filter:brightness(.97)}
:focus-visible{outline:2px solid var(--od-focus);outline-offset:2px}
@media(prefers-color-scheme:dark){
  :root{color-scheme:dark}}
/* Shared primitives: semantics here; state-specific geometry stays in tool-shell.css. */
.od-page{min-width:0}
.od-toolbar{display:flex;align-items:center;gap:var(--space-2);min-width:0}
.od-page-head{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);min-height:var(--od-icon-size);min-width:0}
.od-page-title{min-width:0;margin:0;color:var(--od-ink);font-size:var(--od-note-size);font-weight:600;line-height:1.5;overflow-wrap:anywhere}
.od-page-actions{display:flex;align-items:center;justify-content:flex-end;gap:var(--space-2);min-width:0;flex:none;margin-inline-start:auto}
/* Tools Index/Detail is the trusted Tab header baseline; narrow actions wrap as a group. */
@media(max-width:240px){.od-page-head{flex-wrap:wrap}.od-page-actions{flex-wrap:wrap;max-width:100%}}
.od-stack{display:grid;gap:var(--space-2);min-width:0}
/* Public component contract: semantic appearance lives only here; pages own layout. */
.od-surface{min-width:0;background:var(--od-paper);border:1px solid var(--od-line);border-radius:var(--radius-surface)}
.od-surface--padded{padding:var(--space-3)}
.od-button{display:inline-flex;align-items:center;justify-content:center;gap:var(--space-1);max-width:100%;min-height:36px;padding:var(--space-2) var(--space-3);font:inherit;font-weight:650;border:1px solid var(--od-brand);border-radius:var(--radius-control);background:var(--od-brand);color:var(--od-on-brand);text-align:center}
.od-button--secondary{background:var(--od-action-bg);border-color:var(--od-action-border);color:var(--od-action-ink)}
.od-button--danger{background:var(--od-negative-bg);border-color:var(--od-negative);color:var(--od-negative)}
.od-button--quiet{background:transparent;border-color:transparent;color:var(--od-ink)}
/* Opt-in compact navigation tab: shared focus/disabled semantics, no tool-private button skin. */
.od-button--tab{min-height:0;padding:0;border:0;border-radius:0}
.od-icon-button{position:relative;display:inline-grid;place-items:center;flex:none;width:var(--od-icon-size);height:var(--od-icon-size);min-width:var(--od-icon-size);min-height:var(--od-icon-size);padding:0;border:1px solid var(--od-line);border-radius:var(--radius-control);background:var(--od-paper);color:var(--od-sub)}
.od-icon-button--primary{border-color:var(--od-brand);background:var(--od-brand);color:var(--od-on-brand)}
.od-icon-button--danger{border-color:var(--od-negative);background:var(--od-negative-bg);color:var(--od-negative)}
/* Sandbox consumers receive this public slice without the document button reset. */
.od-button:disabled,.od-icon-button:disabled{opacity:.48;cursor:not-allowed}
/* Opt-in unframed icon action for compact product toolbars.
   Keeps the trusted 34px hit target, focus, disabled and danger semantics. */
.od-icon-button--quiet{border-color:transparent;background:transparent}
.od-icon-button--quiet:hover:not(:disabled){border-color:transparent;background:var(--od-muted)}
.od-icon-button--quiet[aria-expanded=true]{border-color:transparent}
.od-icon-button svg{width:18px;height:18px;display:block;pointer-events:none;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.od-icon-button:hover:not(:disabled):not(.od-icon-button--primary):not(.od-icon-button--danger){background:var(--od-muted)}
.od-icon-button[aria-expanded=true]{background:var(--od-muted);border-color:var(--od-focus);color:var(--od-accent-ink)}
/* R40: Tool/Page header actions are ghost by default; hit targets remain 34px.
   Only hover, focus and expanded state receive a subtle surface. */
.od-page-head .od-icon-button{border-color:transparent;background:transparent;color:var(--od-sub)}
.od-page-head .od-icon-button--primary{color:var(--od-brand)}
.od-page-head .od-icon-button:hover:not(:disabled){border-color:transparent;background:var(--od-muted);color:var(--od-accent-ink)}
.od-page-head .od-icon-button[aria-expanded=true]{border-color:transparent;background:var(--od-muted);color:var(--od-accent-ink)}

:is(input,select,textarea).od-field{min-width:0;border:1px solid var(--od-input-border);border-radius:var(--radius-control);background:var(--od-paper);color:var(--od-ink);font-size:var(--od-body-size)}
:is(input,select,textarea).od-field:disabled,
:is(input,textarea).od-field[readonly]{background:var(--od-muted);color:var(--od-sub)}
:is(input,select,textarea).od-field[aria-invalid="true"]{border-color:var(--od-negative)}
.od-form-field{display:grid;gap:var(--space-1);min-width:0}
.od-field-label{margin:0;font-size:var(--od-note-size);font-weight:650;line-height:1.5;color:var(--od-ink)}
.od-field-help{margin:0;font-size:var(--od-note-size);line-height:1.55;color:var(--od-sub)}
.od-field-error{margin:0;font-size:var(--od-note-size);line-height:1.55;color:var(--od-negative)}
.od-body{color:var(--od-ink);font-size:var(--od-body-size);line-height:1.55;font-weight:400}
.od-note{color:var(--od-sub);font-size:var(--od-note-size);line-height:1.55;font-weight:400}
.od-title{color:var(--od-ink);font-size:var(--od-body-size);line-height:1.5;font-weight:650}
.od-technical{font-size:var(--od-meta-size);line-height:1.55;color:var(--od-sub);font-weight:400;overflow-wrap:anywhere}
.od-result{min-width:0;margin:0;border:1px solid var(--od-line);background:var(--od-muted);border-radius:var(--radius-control);padding:var(--space-2);color:var(--od-ink)}
.od-alert{margin:0;padding:var(--space-3);border:1px solid var(--od-line);border-radius:var(--radius-control);color:var(--od-ink);background:var(--od-muted)}
.od-alert--warning{background:var(--od-warning-bg);border-color:var(--od-warning-border);color:var(--od-warning-ink)}
.od-alert--error{background:var(--od-negative-bg);border-color:var(--od-negative);color:var(--od-negative)}
.od-disclosure{min-width:0;margin:0;border:1px solid var(--od-line);border-radius:var(--radius-surface);background:var(--od-paper);color:var(--od-ink)}
/* All trusted disclosures use the same centered header, marker and type scale.
 * Keep the lighter --flat and emphasis-only --info variants on this one component. */
.od-disclosure>summary{display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-2);min-height:44px;padding:var(--space-2) var(--space-3);list-style:none;cursor:pointer;font-size:var(--od-body-size);line-height:1.5;font-weight:650;color:var(--od-ink);overflow-wrap:anywhere}
.od-disclosure>summary::-webkit-details-marker{display:none}
.od-disclosure>summary::before{content:"";flex:none;width:7px;height:7px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(-45deg)}
.od-disclosure[open]>summary::before{transform:rotate(45deg)}
.od-disclosure>summary>*{min-width:0}
.od-disclosure>summary>span:only-child{flex:1 1 0}
.od-disclosure>summary :is(strong,b){font-size:inherit;font-weight:inherit;color:inherit}
.od-disclosure[open]>summary{border-bottom:1px solid var(--od-line)}
/* One hover contract for every trusted first-level disclosure. */
.od-disclosure>summary:hover{background:var(--od-muted)}
.od-disclosure:not([open])>summary:hover{border-radius:var(--radius-surface)}
.od-disclosure[open]>summary:hover{border-radius:var(--radius-surface) var(--radius-surface) 0 0}
/** Allow 100%-width form fields inside a disclosure without their 12px margins
 * pushing their right edge outside a narrow Side Panel. */
.od-disclosure>:not(summary){min-width:0;max-width:calc(100% - var(--space-3) - var(--space-3));margin:var(--space-2) var(--space-3) 0}
.od-disclosure>:last-child:not(summary){margin-bottom:var(--space-3)}
.od-disclosure--info>summary{color:var(--od-brand)}
.od-disclosure--info[open]>summary{background:var(--od-muted)}
.od-disclosure--flat{border:0;border-radius:0;background:transparent}
.od-disclosure--flat>summary{min-height:36px;padding:var(--space-2) 0;font-size:var(--od-note-size);color:var(--od-sub)}
.od-disclosure--flat[open]>summary{border-bottom:1px solid var(--od-line);background:transparent}
.od-disclosure--flat>:not(summary){max-width:100%;margin:var(--space-2) 0 0}
.od-disclosure--flat>:last-child:not(summary){margin-bottom:0}
/* Technical disclosures stay frameless, including hover treatment. */
.od-disclosure--flat:is(:not([open]),[open])>summary:hover{background:var(--od-muted);border-radius:var(--radius-control)}
.od-segmented{display:flex;width:max-content;max-width:100%;gap:2px;padding:3px;background:var(--od-muted);border:1px solid var(--od-input-border);border-radius:var(--radius-surface)}
.od-segmented>button{min-height:32px;border-radius:var(--radius-control)}

/* Collapsible rows are interactive controls, including nested technical details. */
@media(pointer:coarse){.od-disclosure>summary{min-height:44px}}

/* Opt-in shadcn/ui aria-nova classes translated to canonical selectors.
 * Palette/mapped semantic values remain in design-tokens.css. No Preflight. */
.od-theme-shadcn :is(.od-button,.od-icon-button){box-sizing:border-box}
.od-theme-shadcn .od-button{min-height:32px;padding:0 10px;gap:6px;font-size:14px;font-weight:500;line-height:20px;border:1px solid transparent;box-shadow:none;outline:none;cursor:default;transition:background-color .1s,box-shadow .1s}
.od-theme-shadcn .od-button:hover:not(:disabled){background:color-mix(in oklch,var(--primary) 80%,transparent)}
.od-theme-shadcn .od-button--primary{background:var(--primary);color:var(--primary-foreground)}
.od-theme-shadcn .od-button--primary:hover:not(:disabled){background:color-mix(in oklch,var(--primary) 80%,transparent)}
.od-theme-shadcn .od-button--secondary{background:var(--secondary);color:var(--secondary-foreground)}
.od-theme-shadcn .od-button--secondary:hover:not(:disabled){background:color-mix(in oklch,var(--secondary) 95%,var(--foreground))}
.od-theme-shadcn .od-button--outline{background:var(--background);border-color:var(--border);color:var(--foreground);box-shadow:0 1px 2px #0000000d}
.od-theme-shadcn .od-button--quiet{background:transparent;color:var(--foreground)}
.od-theme-shadcn .od-button--danger{background:var(--od-negative-bg);color:var(--destructive)}
.od-theme-shadcn .od-button--danger:hover:not(:disabled){background:color-mix(in oklch,var(--destructive) 20%,transparent)}
.od-theme-shadcn .od-button--link{background:transparent;color:var(--primary);text-underline-offset:4px}
.od-theme-shadcn .od-button--link:hover:not(:disabled){background:transparent;text-decoration:underline}
.od-theme-shadcn :is(.od-button--quiet,.od-button--outline,.od-icon-button):hover:not(:disabled){background:var(--muted)}
.od-theme-shadcn :is(.od-button,.od-icon-button):hover:not(:disabled){filter:none}
.od-theme-shadcn .od-button[data-size="xs"]{min-height:24px;padding:0 8px;font-size:12px}
.od-theme-shadcn .od-button[data-size="sm"]{min-height:28px;padding:0 10px;font-size:12.8px}
.od-theme-shadcn .od-button[data-size="lg"]{min-height:36px;padding:0 10px}
.od-theme-shadcn :is(.od-button,.od-icon-button):disabled{opacity:.5;cursor:default}
.od-theme-shadcn :is(input,select,textarea).od-field{box-sizing:border-box;width:100%;min-width:0;min-height:32px;padding:4px 10px;font-family:inherit;font-size:14px;line-height:22px;color:var(--foreground);background:transparent;border:1px solid var(--input);border-radius:var(--radius);box-shadow:0 1px 2px #0000000d;outline:none}
.od-theme-shadcn :is(input,select,textarea).od-field::placeholder{color:var(--muted-foreground)}
.od-theme-shadcn :is(input,select,textarea).od-field:disabled{background:var(--muted);opacity:.5;cursor:not-allowed}
.od-theme-shadcn :is(input,textarea).od-field[readonly]{color:var(--foreground);background:var(--muted)}
.od-theme-shadcn :is(.od-button,.od-icon-button,.od-field):focus-visible{outline:none;border-color:var(--ring);box-shadow:0 0 0 3px color-mix(in oklch,var(--ring) 50%,transparent)}
.od-theme-shadcn .od-field[aria-invalid="true"]{border-color:var(--destructive);box-shadow:0 0 0 3px color-mix(in oklch,var(--destructive) 20%,transparent)}
.od-theme-shadcn .od-field-label{font-size:14px;font-weight:500;line-height:20px}
.od-theme-shadcn .od-form-field{gap:8px}
.od-theme-shadcn :is(.od-title,.od-page-title){font-size:14px;font-weight:600;line-height:20px}
.od-theme-shadcn .od-disclosure>summary{font-weight:500;min-height:36px}
.od-theme-shadcn :is(strong,b){font-weight:500}
.od-theme-shadcn .od-shared-card{background:var(--card);border-color:var(--border);box-shadow:none}
.od-theme-shadcn .od-shared-switch{width:32px;height:18.4px;background:var(--input)}
.od-theme-shadcn .od-shared-switch[data-selected]{background:var(--primary)}
.od-theme-shadcn .od-shared-switch-thumb{width:16px;height:16px;margin-left:1px;background:var(--background)}
.od-theme-shadcn .od-shared-switch[data-selected] .od-shared-switch-thumb{transform:translateX(14px)}
.od-theme-shadcn .od-shared-switch[data-focus-visible]{outline:none;box-shadow:0 0 0 3px color-mix(in oklch,var(--ring) 50%,transparent)}
.od-theme-shadcn .od-shared-switch[data-size="sm"]{width:24px;height:14px}
.od-theme-shadcn .od-shared-switch[data-size="sm"] .od-shared-switch-thumb{width:12px;height:12px}
.od-theme-shadcn .od-shared-switch[data-size="sm"][data-selected] .od-shared-switch-thumb{transform:translateX(10px)}
.od-theme-shadcn:is([data-theme="dark"],[data-preview-theme="dark"]) .od-field{background:color-mix(in oklch,var(--input) 30%,transparent)}
.od-theme-shadcn:is([data-theme="dark"],[data-preview-theme="dark"]) .od-field[aria-invalid="true"]{box-shadow:0 0 0 3px color-mix(in oklch,var(--destructive) 40%,transparent)}
.od-theme-shadcn [role="tablist"]{gap:4px}
.od-theme-shadcn [role="tab"]{font-size:14px;font-weight:500}
.od-theme-shadcn [role="tab"][aria-selected="true"]{color:var(--foreground)}
.od-theme-shadcn .od-button--tab{border:0;border-bottom:2px solid transparent;border-radius:0;background:transparent;box-shadow:none}
.od-theme-shadcn .od-button--tab[aria-selected="true"]{border-bottom-color:var(--foreground)}
